import {createServer,type Server} from "node:http";import {expect,test,vi} from "vitest";import {articleDocument,createApplicationServer,csrDocument,staticSnapshot,streamArticle} from "./rendering.server";import {sample,parseArticle} from "./articleModel";import {createRevalidatedPages} from "./revalidation";async function withServer<T>(server:Server,run:(url:string)=>Promise<T>){await new Promise<void>(resolve=>server.listen(0,"127.0.0.1",resolve));const address=server.address();if(!address||typeof address==="string")throw Error("Brak portu");try{return await run("http://127.0.0.1:"+address.port);}finally{server.closeAllConnections();await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}}function deferred<T>(){let resolve!:(value:T)=>void;const promise=new Promise<T>(yes=>{resolve=yes;});return {promise,resolve};}
test("SSR zawiera artykuł w odpowiedzi HTTP, CSR ma pusty root",async()=>{const load=vi.fn(async()=>sample);await withServer(createApplicationServer(load),async url=>{const response=await fetch(url+"/articles/reset-hasla"),html=await response.text();expect(response.status).toBe(200);expect(response.headers.get("content-type")).toContain("text/html");expect(response.headers.get("cache-control")).toBe("no-store");expect(html).toContain(sample.body);expect(html).toContain("2026-10-01</time>");expect(load).toHaveBeenCalledWith("reset-hasla");});expect(csrDocument()).toContain('<div id="root"></div>');expect(csrDocument()).not.toContain(sample.body);});
test("brak i prywatny artykuł mają 404 bez treści",async()=>{for(const value of [null,{...sample,audience:"private"}])await withServer(createApplicationServer(async()=>value),async url=>{const response=await fetch(url+"/articles/reset-hasla");expect(response.status).toBe(404);expect(await response.text()).not.toContain(sample.body);});});
test("niepoprawna trasa i metoda nie uruchamiają repozytorium",async()=>{const load=vi.fn(async()=>sample);await withServer(createApplicationServer(load),async url=>{expect((await fetch(url+"/articles/reset-hasla",{method:"POST"})).status).toBe(405);expect((await fetch(url+"/other")).status).toBe(404);expect((await fetch(url+"/articles/-bad")).status).toBe(404);});expect(load).not.toHaveBeenCalled();});
test("błąd loadera ma 500 i nie ujawnia szczegółów wyjątku",async()=>{const report=vi.fn();await withServer(createApplicationServer(async()=>{throw Error("sekret DB");},report),async url=>{const response=await fetch(url+"/articles/reset-hasla");expect(response.status).toBe(500);expect(await response.text()).toBe("Błąd serwera");});expect(report).toHaveBeenCalledTimes(1);});
test("HTML i początkowy JSON nie wykonują danych wyglądających jak skrypt",()=>{const html=articleDocument({...sample,body:'</script><script>alert(1)</script>'});expect(html).not.toContain('<script>alert(1)</script>');expect(html).toContain('\\u003c/script\\u003e');expect(html).toContain('&lt;script&gt;');});
test("snapshot SSG powstaje raz i nie zmienia się po edycji repozytorium",async()=>{let current={...sample};const load=vi.fn(async()=>current);const pages=await staticSnapshot([sample.slug],load);current={...sample,body:"Nowa wersja"};expect(pages["articles/reset-hasla/index.html"]).toContain(sample.body);expect(pages["articles/reset-hasla/index.html"]).not.toContain("Nowa wersja");expect(load).toHaveBeenCalledTimes(1);await expect(staticSnapshot([sample.slug,sample.slug],load)).rejects.toThrow("Powtórzony");});
test("ISO odrzuca nieistniejący dzień zamiast normalizować go na kolejny miesiąc",()=>{expect(()=>parseArticle({...sample,updatedAt:"2026-02-30T10:00:00Z"},sample.slug)).toThrow("data kalendarzowa");expect(parseArticle({...sample,updatedAt:"2024-02-29T10:00:00Z"},sample.slug).updatedAt).toBe("2024-02-29T10:00:00.000Z");});
test("SSG odrzuca prywatną publikację i obce ID odpowiedzi",async()=>{await expect(staticSnapshot([sample.slug],async()=>({...sample,audience:"private"}))).rejects.toThrow("prywatnej");expect(()=>parseArticle({...sample,slug:"other"},sample.slug)).toThrow();});
test("rewalidacja blokująca pobiera nowy HTML po TTL",async()=>{let now=0,calls=0;const pages=createRevalidatedPages(async()=>"v"+(++calls),100,()=>now);expect(await pages.get("a")).toBe("v1");now=99;expect(await pages.get("a")).toBe("v1");now=100;expect(await pages.get("a")).toBe("v2");expect(calls).toBe(2);});
test("wspólna regeneracja deduplikuje równoczesne odczyty",async()=>{const task=deferred<string>(),load=vi.fn(()=>task.promise),pages=createRevalidatedPages(load,100,()=>0);const first=pages.get("a"),second=pages.get("a");expect(first).toBe(second);task.resolve("html");expect(await first).toBe("html");expect(load).toHaveBeenCalledTimes(1);});
test("inwalidacja w trakcie starego odczytu nie zatruwa nowego cache",async()=>{const old=deferred<string>(),fresh=deferred<string>(),load=vi.fn().mockReturnValueOnce(old.promise).mockReturnValueOnce(fresh.promise),pages=createRevalidatedPages(load,100,()=>0);const first=pages.get("a");await Promise.resolve();pages.invalidate("a");const second=pages.get("a");await Promise.resolve();fresh.resolve("nowe");expect(await second).toBe("nowe");old.resolve("stare");expect(await first).toBe("stare");expect(await pages.get("a")).toBe("nowe");});
test("błąd regeneracji może zachować ostatnią publiczną wersję, pierwszy błąd odrzuca",async()=>{let now=0;const load=vi.fn().mockResolvedValueOnce("v1").mockRejectedValue(Error("offline")),pages=createRevalidatedPages(load,10,()=>now);expect(await pages.get("a")).toBe("v1");now=10;expect(await pages.get("a")).toBe("v1");await expect(pages.get("b")).rejects.toThrow("offline");});
test("prawdziwy stream wysyła shell przed odblokowaniem treści",async()=>{const task=deferred<typeof sample>();await withServer(createServer((_req,response)=>{streamArticle(task.promise,response);}),async url=>{let reader:ReadableStreamDefaultReader<Uint8Array>|undefined;try{const response=await fetch(url);reader=response.body!.getReader();const first=await reader.read(),initial=new TextDecoder().decode(first.value);expect(initial).toContain("Baza wiedzy");expect(initial).toContain("Ładowanie artykułu");expect(initial).not.toContain(sample.body);task.resolve(sample);let rest="";for(;;){const chunk=await reader.read();if(chunk.done)break;rest+=new TextDecoder().decode(chunk.value);}expect(rest).toContain(sample.body);}finally{task.resolve(sample);await reader?.cancel();}});});

